<?php
/** Server-rendered presentation for the team archive. */
use yii\helpers\Html;
?>
<?php use yii\widgets\ActiveForm; $this->title = '留言交流 · 星河工坊'; ?><div class="page-heading"><span class="eyebrow">HELLO, WORLD. HELLO, YOU.</span><h1>你的声音，我们认真倾听。</h1><p>分享灵感、提出建议，或只是打个招呼。公开留言将在审核后展示。</p></div><div class="detail-grid"><section><h2>交流广场</h2><?php foreach ($messages as $message): ?><article class="message-card"><div class="card-meta"><strong><?= Html::encode($message['name'] ?? $message['author_name'] ?? '访客') ?></strong><time><?= Html::encode(substr($message['created_at'] ?? '',0,10)) ?></time></div><p><?= nl2br(Html::encode($message['body'] ?? '')) ?></p><?php foreach ($message['replies'] ?? [] as $reply): ?><div class="reply"><strong>工坊回复</strong><p><?= nl2br(Html::encode($reply['body'] ?? '')) ?></p></div><?php endforeach ?></article><?php endforeach ?><?php if (!$messages): ?><p class="empty-state">成为第一位给工坊留言的朋友吧。</p><?php endif ?></section><aside class="panel form-panel"><h2>留下一点灵感</h2><?php $activeForm = ActiveForm::begin(['enableClientScript'=>false,'enableClientValidation'=>false]); ?><?= $activeForm->field($form,'name')->textInput(['maxlength'=>80,'placeholder'=>'我们该怎么称呼你？'])->label('你的称呼') ?><?= $activeForm->field($form,'email')->input('email',['placeholder'=>'仅用于联系，不会公开'])->label('电子邮箱') ?><?= $activeForm->field($form,'body')->textarea(['rows'=>6,'maxlength'=>2000,'placeholder'=>'想对我们说些什么？'])->label('留言内容') ?><div class="honeypot" aria-hidden="true"><?= $activeForm->field($form,'website')->textInput(['tabindex'=>-1,'autocomplete'=>'off'])->label('Website') ?></div><?= Html::submitButton('发送留言 ↗',['class'=>'button']) ?><p class="form-note">请勿提交密码、身份证号等敏感信息。</p><?php ActiveForm::end(); ?></aside></div>
